INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (1, 20063115, "フリーマーケットを訪れたジータが出会ったのは\n城をこっそり抜け出していたペコリーヌだった。", 10118, 40, 7, "青空の下で謁見", 5118061, 2, 0, 91002, "ペコリーヌとの出会い", 2834, 8, "フリーマーケット会場");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (1, 20063115, "ジータたちがフリーマーケットを巡っていると\n露店を出していたマホに声をかけられる。", 10118, 40, 7, "未来の騎空団\nマスコット？", 5118062, 2, 0, 91002, "マホとの出会い", 2835, 8, "フリーマーケット会場");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (1, 20063115, "ジータが騎空団への依頼を確認していると、\n高笑いをしながらアキノが現れる。", 10118, 40, 7, "お嬢さまからの\n緊急依頼", 5118063, 2, 0, 91002, "アキノとの出会い", 2837, 8, "ランドソル市街地");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (1, 20063115, "ジータたちは、フリーマーケット会場で\n少し困った様子のジュンを見かける。", 10118, 40, 18, "黄金色の悩みごと", 5118064, 2, 0, 91002, "ジュンとの出会い", 4108402, 8, "フリーマーケット会場");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (1, 20063115, "フリーマーケットの隅で開かれる格闘大会──\nそこにはカオリもいて……？", 10118, 40, 18, "白熱！　格闘大会！", 5118065, 2, 0, 91002, "カオリとの出会い", 4107402, 8, "フリーマーケット会場");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (1, 20063115, "太鼓祭を控えるオーエド町──\nジータは、困った様子のニノンと出会う。", 10118, 40, 16, "祭り太鼓はオーエドの華", 5118066, 2, 1, 91002, "ニノンとの出会い", 9000227, 8, "オーエド町");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (1, 20063115, "ビカラはイベントに出演中のスズナを見かける。\nしかし、スズナはどこか困っているようで……？", 10118, 40, 19, "人気者は遅れて\nやってくる", 5118067, 3, 0, 91002, "スズナとの出会い", 2101181, 8, "フリーマーケット会場");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (1, 20063115, "ビカラたちが街を散策していると、通りかかった\nナナカが興奮した様子で近づいてきて……？", 10118, 40, 18, "巫女・ミーツ・魔法少女", 5118068, 3, 0, 91002, "ナナカとの出会い", 4109402, 8, "ランドソル市街地");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (1, 20063115, "ネズ耳をなくしてしまい絶望するビカラ。同じ頃\nキャルとコッコロは落とし物を拾っており……", 10118, 40, 18, "ネズ耳は二度なくなる", 5118069, 3, 0, 91002, "キャル＆コッコロとの出会い", 4305402, 8, "フリーマーケット会場");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (1, 20063115, "街外れでひと休みをしていたビカラたちは、\nすっかりゴキゲンな様子のユカリと出会う。", 10118, 40, 18, "この出会いにカンパイ！", 5118070, 3, 0, 91002, "ユカリとの出会い", 4101402, 8, "ランドソル市街地");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (1, 20063115, "ビカラは、人混みに怯えるアオイを心配し、\n陽気に声をかけるも……", 10118, 40, 18, "陰陽アンサンブル", 5118071, 3, 0, 91002, "アオイとの出会い", 4106402, 8, "ランドソル市街地");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (1, 20063115, "ビカラがフリーマーケット会場を歩いていると\n占いをしていたシノブに声をかけられる。", 10118, 40, 7, "運試し十番勝負！", 5118072, 3, 1, 91002, "シノブとの出会い", 2836, 8, "フリーマーケット会場");
INSERT INTO `v1_5b2831a3eb9f8aaa2bec58be2915b4ddea574a3b2a633fc098650e4846dddf40` VALUES (0, 20063115, 0, 10118, 0, 0, "彼女たちの新たな日常", 5118600, 1, 0, 0, "オープニング", 0, 0, 0);
